./executable --kinds-C=* -o - /tmp/c_more.c 2>&1
./executable --fields=* -o - /tmp/c_more.c 2>&1 | head -n 100

# Test C with if0
./executable --if0=no -o - /tmp/c_more.c 2>&1 | head -n 20
./executable --if0=yes -o - /tmp/c_more.c 2>&1 | head -n 20

# Test macro handling
