# Tag structure
class Tag:
    def __init__(self, name, path, pattern, kind, kind_long, line, typeref=None, scope=None, scopeKind=None, file=False, extras=None):
        self.name=name
        self.path=path
        self.pattern=pattern
        self.kind=kind
        self.kind_long=kind_long
        self.line=line
        self.typeref=typeref
        self.scope=scope
        self.scopeKind=scopeKind
        self.file=file
        self.extras=extras or []
        self.fields={}
        self.roles=[]
        self.language=None

def escape_pattern(line, limit=96):
    # Implement escaping as deduced
    # input line is original line without newline, keep as is
    # We need to produce escaped version up to limit
    # If limit==0, no limit
    # Also handle $ at end escaping
    # Process: iterate over characters, building escaped string, counting escaped length
    # If limit>0 and next escaped token would exceed limit, stop
    # At the end, determine if truncated
    escaped=""
    orig_len=0
    # We'll process character by character
    for idx, ch in enumerate(line):
        # Determine escaped representation
        if ch == "/":
            esc = "\\/"
        elif ch == "\\":
            esc = "\\\\"
        elif ch == "$" and idx == len(line)-1:
            # last char and is $
            esc = "\\$"
        else:
            esc = ch
        if limit>0 and len(escaped)+len(esc) > limit:
            # If limit is cut, we may need to check if we are in middle of escaping? We already check len
            break
        escaped+=esc
        orig_len=idx+1
    truncated = (orig_len < len(line)) if limit>0 else False
    # Build final pattern: "/^" + escaped + ( "$" if not truncated else "") + "/"
    # Actually original pattern format: "/^<pattern>$/;" or "/^<pattern>/;" if truncated
    # For empty? etc.
    if truncated:
        return f"/^{escaped}/"
    else:
        return f"/^{escaped}$/"

def make_pattern(line, limit=96):
    return escape_pattern(line.rstrip("\n"), limit)

