            t=Tag(name, file_path, pat, 'i', 'interface', idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*type\s+([A-Za-z_]\w*)\s+', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 't', 'type', idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        # var
        m=re.match(r'^\s*var\s+([A-Za-z_]\w*)', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'v', 'var', idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        # const
        m=re.match(r'^\s*const\s+([A-Za-z_]\w*)', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'c', 'const', idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue

def parse_markdown(file_path, content, tags):
    lines=content.splitlines()
    # Track title hierarchy for scope
    # According to observed, # Title is chapter, ## Section is section with scope Title
    # ### Subsection is subsection with scope Title""Section? Actually observed: Subsection scope "Title""Section"? Wait earlier we had Title""Section? Let's re-evaluate
    # Output for markdown test: Another scope Title, Section scope Title, Subsection scope Title""Section (weird double quotes)
    # So for ###, scope is previous # and ## concatenated with ""?
    # We'll implement simple: keep stack of headings by level
    headings=[]  # list of (level, name)
    for idx, line in enumerate(lines, start=1):
        m=re.match(r'^(#{1,5})\s+(.*\S)\s*$', line)
        if m:
            level=len(m.group(1))
            name=m.group(2).strip()
            # Determine kind
            if level==1:
                kind='c'; kind_long='chapter'
            elif level==2:
                kind='s'; kind_long='section'
            elif level==3:
                kind='t'; kind_long='subsubsection'
            elif level==4:
                kind='T'; kind_long='l4subsection'
            elif level==5:
                kind='u'; kind_long='l5subsection'
            else:
                kind='s'; kind_long='section'
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, kind, kind_long, idx)
            t.language='Markdown'
            # scope: find parent heading
            # For level 2, parent is last level 1
            # For level 3, parent is last level 2, but scope string in observed was Title""Section ? Actually scope "Title""Section" would be chapter + section concatenated? Let's set scope as immediate parent name, but for level 3 they had scope "Title""Section" which seems like concatenation of Title and Section? Could be they join with ""? We'll just set scope to parent name for simplicity, but to match observed we need to output same as original for our test file.
            # Our test file had: # Title, ## Section, ### Subsection, ## Another
            # Original output:
            # Another scope Title (so ## Another scope Title)
            # Section scope Title
            # Subsection scope Title""Section
            # Title no scope
            # So for Subsection (level 3), scope was Title""Section - which includes both Title and Section separated by ""? That's strange: maybe they use "" as separator for multiple scopes? Could be they use "" to separate scope chain? For level 2, scope is Title, for level 3, scope is Title and Section? They show "Title""Section" meaning two scopes: Title and Section? But our simple implementation would give scope Section only.
            # Let's try to match: For Subsection, parent is Section, grandparent Title, so full scope chain is Title, Section. They display as "Title""Section"? That could be representation of scope chain with ""? In ctags, scope field can be "scope:..." but with multiple? Actually for Markdown, they might have chapter and section as separate fields? But in observed JSON, Subsection had scope "Title""Section" and scopeKind "section". That suggests they stored scope as "Title""Section"? Could be Title is chapter, Section is section, and they join with ""? Let's assume for Markdown, scope is concatenation of all parent headings with ""? Or maybe they use "" as separator for multiple parent levels?
            # For simplicity, we will produce scope as immediate parent only, unless level>2 then join with ""? Let's implement: for level 2, scope = last level1 name. For level 3, scope = last level1 + "\"\"" + last level2? That matches observed: Title + "" + Section = Title""Section.
            # For level 4, maybe scope = Title""Section""Subsection etc? We'll implement accumulating with "" separator.
            # Let's build headings list and for current level, find parents of lower levels.
            # Accumulate scope chain as "" joined.
            parent_names = [h[1] for h in headings if h[0] < level]
            if parent_names:
                if len(parent_names)==1:
                    t.scope = parent_names[0]
                    # scopeKind based on parent level
                    parent_level = [h[0] for h in headings if h[0] < level][-1]
                    if parent_level==1:
                        t.scopeKind='chapter'
                    elif parent_level==2:
                        t.scopeKind='section'
                    elif parent_level==3:
                        t.scopeKind='subsubsection'
                    else:
                        t.scopeKind='section'
                else:
                    # join with "" as observed
                    t.scope = "\"\"".join(parent_names)
                    # scopeKind is immediate parent kind
                    parent_level = [h[0] for h in headings if h[0] < level][-1]
                    if parent_level==1:
                        t.scopeKind='chapter'
                    elif parent_level==2:
                        t.scopeKind='section'
                    elif parent_level==3:
                        t.scopeKind='subsubsection'
                    else:
                        t.scopeKind='section'
            # Remove headings of same or higher level
            headings = [h for h in headings if h[0] < level]
            headings.append((level, name))
            tags.append(t)

def parse_sh(file_path, content, tags):
    lines=content.splitlines()
    for idx, line in enumerate(lines, start=1):
        m=re.match(r'^\s*([A-Za-z_]\w*)\s*\(\)\s*\{', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'f', 'function', idx)
            t.language='Sh'
            tags.append(t)

