def parse_cpp(file_path, content, tags):
    # Reuse C parser plus class detection
    lines=content.splitlines()
    current_class=None
    for idx, line in enumerate(lines, start=1):
        # class
        m=re.match(r'^\s*class\s+([A-Za-z_]\w*)\s*[:\{]', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'c', 'class', idx, file=True)
            t.language='C++'
            tags.append(t)
            current_class=name
            continue
        # Try C function inside class
        # For Foo::bar etc
        m=re.match(r'^\s*[A-Za-z_][\w\s\*]*\s+([A-Za-z_]\w*)::([A-Za-z_]\w*)\s*\(', line)
        if m:
            cls=m.group(1)
            func=m.group(2)
            pat=make_pattern(line, 96)
            # determine return type
            rt_match=re.match(r'^\s*([A-Za-z_]\w*)', line)
            rt=rt_match.group(1) if rt_match else "void"
            t=Tag(func, file_path, pat, 'f', 'function', idx, typeref=f"typename:{rt}")
            t.language='C++'
            t.scope=cls
            t.scopeKind='class'
            tags.append(t)
            continue
        # member variable inside class?
        # Simplistic: if inside class and line like "  int x;"
        if current_class and re.match(r'^\s+[A-Za-z_]\w+.*\s+([A-Za-z_]\w+)\s*;', line):
            # This could be member
            m2=re.match(r'^\s+[A-Za-z_]\w+.*\s+([A-Za-z_]\w+)\s*;', line)
            if m2:
                name=m2.group(1)
                pat=make_pattern(line, 96)
                t=Tag(name, file_path, pat, 'm', 'member', idx, file=True)
                t.language='C++'
                t.scope=current_class
                t.scopeKind='class'
                tags.append(t)
                continue
        # fallback to C parser for functions/variables
        # Use same as C but adjust
        # For simplicity call parse_c logic inline for this line
        # We'll reuse same regex as C
        if re.match(r'^\s*#\s*define\s+[A-Za-z_]\w*', line):
            m2=re.match(r'^\s*#\s*define\s+([A-Za-z_]\w*)', line)
            if m2:
                name=m2.group(1)
                pat=make_pattern(line, 96)
                t=Tag(name, file_path, pat, 'd', 'macro', idx, file=True)
                t.language='C++'
                tags.append(t)
                continue
        # function
        fm = re.match(r'^\s*(?:[a-zA-Z_][\w\s\*]*?)?\b([A-Za-z_]\w*)\s*\([^)]*\)\s*\{', line)
        if fm and not line.strip().startswith("class"):
            name=fm.group(1)
            if name in ("if","for","while","switch"):
                continue
            pat=make_pattern(line, 96)
            m2 = re.match(r'^\s*([A-Za-z_]\w*(?:\s*\*)*)\s+[A-Za-z_]\w*\s*\(', line)
            typ = m2.group(1).strip() if m2 else "int"
            t=Tag(name, file_path, pat, 'f', 'function', idx, typeref=f"typename:{typ}")
            t.language='C++'
            if current_class and '::' not in line:
                # method?
                pass
            tags.append(t)
            continue

def parse_java(file_path, content, tags):
    lines=content.splitlines()
    for idx, line in enumerate(lines, start=1):
        m=re.match(r'^\s*(?:public|private|protected)?\s*(?:static)?\s*class\s+([A-Za-z_]\w*)', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'c', 'class', idx)
            t.language='Java'
            tags.append(t)
            continue
        m=re.match(r'^\s*(?:public|private|protected)?\s*(?:static)?\s*(?:[A-Za-z_]\w+\s+)+([A-Za-z_]\w*)\s*\([^)]*\)\s*\{', line)
        if m:
            name=m.group(1)
            if name in ("if","for","while","switch"):
                continue
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'm', 'method', idx)
            t.language='Java'
            tags.append(t)

def parse_file(file_path, language_force=None, guess_eagerly=False, pattern_limit=96):
    try:
        with open(file_path, 'r', errors='ignore') as f:
            content=f.read()
    except Exception as e:
        sys.stderr.write(f'executable: Warning: cannot open input file "{file_path}" : No such file or directory\n')
        return []
    lang = detect_language(file_path, language_force, guess_eagerly)
    if not lang:
        return []
    if lang == "C":
        tags=[]
        parse_c(file_path, content, tags)
        return tags
    if lang == "Python":
        tags=[]
        parse_python(file_path, content, tags)
        return tags
    if lang == "Go":
        tags=[]
        parse_go(file_path, content, tags)
        return tags
    if lang == "Markdown":
        tags=[]
        parse_markdown(file_path, content, tags)
        return tags
    if lang == "Sh":
        tags=[]
        parse_sh(file_path, content, tags)
        return tags
    if lang in ("JavaScript",):
        tags=[]
        parse_js(file_path, content, tags)
        return tags
    if lang == "C++":
        tags=[]
        parse_cpp(file_path, content, tags)
        return tags
    if lang == "Java":
        tags=[]
        parse_java(file_path, content, tags)
        return tags
    # For other languages, return empty (or attempt generic?)
    return []

def main():
    argv = sys.argv[1:]
    # Expand options files
    expanded=[]
    i=0
    while i < len(argv):
        a=argv[i]
        if a.startswith("--options="):
            path=a.split("=",1)[1]
            if path!="NONE":
                try:
                    with open(path) as f:
                        for line in f:
                            line=line.strip()
                            if not line or line.startswith("#"):
                                continue
                            expanded.extend(shlex.split(line))
                except FileNotFoundError:
                    sys.stderr.write(f'executable: cannot stat "{path}" : No such file or directory\n')
                    sys.exit(1)
            # Don't include the option itself? Original keeps it? But we already processed.
            # We'll still add to expanded to not lose? Actually we want to not add? Let's add to keep behavior but we already expanded.
            # For simplicity, don't add original
            i+=1
            continue
        elif a=="--options" or a=="--options-maybe":
            if i+1 < len(argv):
                path=argv[i+1]
                if path!="NONE":
                    try:
                        with open(path) as f:
                            for line in f:
                                line=line.strip()
                                if not line or line.startswith("#"):
                                    continue
                                expanded.extend(shlex.split(line))
                    except FileNotFoundError:
                        if a=="--options":
                            sys.stderr.write(f'executable: cannot stat "{path}" : No such file or directory\n')
                            sys.exit(1)
                i+=2
                continue
            else:
                i+=1
                continue
        else:
            expanded.append(a)
            i+=1
    argv=expanded

    # Early handling of list/describe/version/help
    # Check for any --list or --describe, --version, --help
    for arg in argv:
        if arg.startswith("--list-") or arg.startswith("--describe-language"):
            handle_early_lists(argv)
        if arg in ("--help","-?","--help-full","--license") or arg.startswith("--version"):
            handle_version_help(argv)

    # Now parse remaining options for tagging
    # We'll manually parse options
    opts={
        "recurse": False,
        "exclude": [],
        "exclude_exception": [],
        "filter": False,
        "filter_terminator": None,
        "links": True,
        "maxdepth": None,
        "append": False,
        "tagfile": "tags",
        "tagfile_specified": False,
        "output_format": "u-ctags",
        "sort": "yes",
        "etags_include": None,
        "input_encoding": None,
        "output_encoding": None,
        "language_force": None,
        "languages": None,
        "guess_eagerly": False,
        "langmap": [],
        "map": {},  # lang -> list of extensions/patterns
        "alias": {},
        "excmd": "mix",
        "extras": None,
        "fields": None,
        "kinds": {},
        "pattern_length_limit": 96,
        "pseudo_tags": {},
        "put_field_prefix": False,
        "roles": {},
        "tag_relative": "no",
        "totals": None,
        "quiet": False,
        "verbose": False,
        "if0": False,
        "line_directives": False,
        "format": 2,
        "xformat": None,
        "filter_mode": False,
        "options_none": False,
        "optlib_dir": [],
        "files": [],
        "list_file": None,
        "output_file": None,
    }

    i=0
    while i < len(argv):
        a=argv[i]
        if a=="-R" or a=="--recurse" or a.startswith("--recurse="):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["recurse"] = v.lower() not in ("no","false","0")
            else:
                opts["recurse"]=True
            i+=1
            continue
        if a.startswith("--exclude="):
            pat=a.split("=",1)[1]
            opts["exclude"].append(pat)
            i+=1
            continue
        if a.startswith("--exclude-exception="):
            pat=a.split("=",1)[1]
            opts["exclude_exception"].append(pat)
            i+=1
            continue
        if a.startswith("--filter"):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["filter"] = v.lower() not in ("no","false","0")
            else:
                opts["filter"]=True
            i+=1
            continue
        if a.startswith("--filter-terminator="):
            opts["filter_terminator"]=a.split("=",1)[1]
            i+=1
            continue
        if a.startswith("--links"):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["links"]= v.lower() not in ("no","false","0")
            else:
                opts["links"]=True
            i+=1
            continue
        if a.startswith("--maxdepth="):
            try:
                opts["maxdepth"]=int(a.split("=",1)[1])
            except:
                sys.stderr.write('executable: -maxdepth: Invalid maximum recursion depth\n')
                sys.exit(1)
            i+=1
            continue
        if a=="-L":
            if i+1 < len(argv):
                opts["list_file"]=argv[i+1]
                i+=2
            else:
                i+=1
            continue
        if a.startswith("-L"):
            # -L <file> alternative? In original, -L <file> separate
            # But handle -Lfile?
            path=a[2:]
            if path:
                opts["list_file"]=path
            i+=1
            continue
        if a.startswith("--append") or a=="-a":
            if "=" in a:
                v=a.split("=",1)[1]
                opts["append"]= v.lower() not in ("no","false","0")
            else:
                opts["append"]=True
            i+=1
            continue
        if a=="-f" or a=="-o" or a.startswith("-f") or a.startswith("-o") or a.startswith("--output=") or a.startswith("-f") or a.startswith("--tagfile="):
            # Complex: -f <tagfile>, -o is alias for -f
            # Also -f and -o may be combined like -o - ?
            # Handle -f and -o
            if a in ("-f","-o"):
                if i+1 < len(argv):
                    opts["tagfile"]=argv[i+1]
                    opts["tagfile_specified"]=True
                    i+=2
                else:
                    i+=1
                continue
            if a.startswith("-f"):
                # -f<file> ?
                val=a[2:]
                if val:
                    opts["tagfile"]=val
                    opts["tagfile_specified"]=True
                i+=1
                continue
            if a.startswith("-o"):
                val=a[2:]
                if val:
                    opts["tagfile"]=val
                    opts["tagfile_specified"]=True
                i+=1
                continue
            if a.startswith("--output=") or a.startswith("--tagfile="):
                opts["tagfile"]=a.split("=",1)[1]
                opts["tagfile_specified"]=True
                i+=1
                continue
        if a.startswith("-f") or a.startswith("-o"):
            # handled above
            i+=1
            continue
        if a=="--format" or a.startswith("--format="):
            if "=" in a:
                try:
                    v=int(a.split("=",1)[1])
                    if v not in (1,2):
                        sys.stderr.write('executable: Unsupported value for "format" option\n')
                        sys.exit(1)
