            continue
        if a.startswith("--output-format="):
            fmt=a.split("=",1)[1]
            if fmt not in ("u-ctags","e-ctags","etags","xref","json"):
                sys.stderr.write(f'executable: unknown output format name supplied for \"output-format={fmt}\"\n")
                sys.exit(1)
            opts["output_format"]=fmt
            i+=1
            continue
        if a=="-e":
            opts["output_format"]="etags"
