                    clean.append(l.split()[0])
            # For language-force, also allow auto
            lang_force = opts["language_force"]
            if lang_force!="auto" and lang_force not in clean and lang_force not in ("C","Python","Go","Java","JavaScript","Sh","Markdown","C++","C","JavaScript","Sh"):
