def detect_language(file_path, force=None, guess_eagerly=False):
    if force and force != "auto":
        return force
    # by extension
    ext = os.path.splitext(file_path)[1].lower()
    lang = EXT_MAP.get(ext)
    if lang:
        return lang
    # try pattern mappings: Make, etc.
    base = os.path.basename(file_path)
    if base in ("Makefile", "GNUmakefile", "makefile"):
        return "Make"
    if base == "CMakeLists.txt":
        return "CMake"
    if base == "Cargo.toml":
        return "Cargo"
    # Check shebang if guess_eagerly or file executable?
    try:
        with open(file_path, 'r', errors='ignore') as f:
            first = f.readline()
            if first.startswith("#!"):
                if "python" in first:
                    return "Python"
                if "bash" in first or "sh" in first:
                    return "Sh"
                if "node" in first:
                    return "JavaScript"
    except:
        pass
    return None

# Simple parsers
def parse_c(file_path, content, tags):
    lines = content.splitlines()
    for idx, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#") and not stripped.startswith("#define"):
            # macro handled separately
            pass
        # macro
        m = re.match(r'^\s*#\s*define\s+([A-Za-z_]\w*)', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'd', 'macro', idx, file=True)
            t.language='C'
            tags.append(t)
            continue
        # enum enumerator - we handle via enum parsing? For simplicity, skip complex enum; but detect "RED, GREEN, BLUE" inside enum
        # We'll attempt to detect enum definition and enumerators
        # Already we have macro, now function/variable
        # Skip if line is inside enum? We'll do simple enum enumerator detection via regex for lines inside enum braces?
        # For simplicity, we implement:
        # - function definition: pattern like "type name(args) {"
        # Regex for C function
        # This is simplistic but matches our test cases
        # function: ^\s*[a-zA-Z_][\w\s\*]*\s+([a-zA-Z_]\w*)\s*\([^)]*\)\s*\{?\s*$
        # But need to exclude if, for, while, switch
        if re.match(r'^\s*(if|for|while|switch|return)\b', stripped):
            continue
        # typedef struct etc handled later
        # Try function
        fm = re.match(r'^\s*(?:[a-zA-Z_][\w\s\*]*?)?\b([A-Za-z_]\w*)\s*\([^)]*\)\s*\{', line)
        if fm:
            name=fm.group(1)
            # filter keywords
            if name in ("if","for","while","switch","return"):
                continue
            # Ensure not variable assignment containing '('?
            # For our simple test, treat as function
            pat=make_pattern(line, 96)
            # Determine typeref: try to extract return type
            # Simplistic: everything before name is return type
            before = line[:fm.start(1)]
            # Remove static etc
            rt = before.strip().split()[-1] if before.strip() else "int"
            # Clean rt
            rt = rt.replace("*","").strip() or "int"
            # For our test, use int or void etc - we can attempt to parse first word as type
            # Actually for "int main() {" return type is int
            # For "void foo() {}" void
            # We'll use simple extraction
            # Let's get return type via regex of line start
            m2 = re.match(r'^\s*([A-Za-z_]\w*(?:\s*\*)*)\s+[A-Za-z_]\w*\s*\(', line)
            typ = m2.group(1).strip() if m2 else "int"
            typ = typ.replace(" ","")
            t=Tag(name, file_path, pat, 'f', 'function', idx, typeref=f"typename:{typ}")
            t.language='C'
            tags.append(t)
            continue
        # variable definition: ^\s*(?:static\s+|extern\s+|const\s+)*\s*[\w]+\s+([A-Za-z_]\w*)\s*(?:=|;)
        vm = re.match(r'^\s*(?:static\s+|extern\s+|const\s+)*(?:[A-Za-z_]\w*\s+)+([A-Za-z_]\w*)\s*(?:=|;|\[)', line)
        if vm:
            name=vm.group(1)
            # Avoid keywords and already captured function names
            if name in ("return","struct","enum","union","typedef","int","char","void","long","short","float","double"):
                continue
            # Check if this line contains '(' - would be function prototype, skip
            if '(' in line and ')' in line and '{' not in line:
                # Could be prototype but we ignore unless it's variable
                # For "int bar = 42;" this matches variable
                # For "int add(int a, int b) {" we already matched function earlier, so skip
                pass
            pat=make_pattern(line, 96)
            # typeref
            m2 = re.match(r'^\s*(?:static\s+|extern\s+|const\s+)*([A-Za-z_]\w*(?:\s*\*)*)', line)
            typ = m2.group(1).strip() if m2 else "int"
            typ = typ.split()[0]
            t=Tag(name, file_path, pat, 'v', 'variable', idx, typeref=f"typename:{typ}")
            t.language='C'
            # file scope if static?
            if 'static' in line:
                t.file=True
            tags.append(t)
            continue
        # struct, enum, typedef, etc - minimal
        sm = re.match(r'^\s*struct\s+([A-Za-z_]\w*)\s*\{', line)
        if sm:
            name=sm.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 's', 'struct', idx, file=True)
            t.language='C'
            tags.append(t)
            continue
        em = re.match(r'^\s*enum\s+([A-Za-z_]\w*)\s*\{', line)
        if em:
            name=em.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'g', 'enum', idx, file=True)
            t.language='C'
            tags.append(t)
            continue
        # typedef
        tm = re.match(r'^\s*typedef\s+struct\s*\{', line)
        if tm:
            # need closing } Name; later, so handle later
            continue

def parse_python(file_path, content, tags):
    lines = content.splitlines()
    stack = []  # list of (indent, name, kind)
    for idx, line in enumerate(lines, start=1):
        # Compute indent
        indent_match = re.match(r'^(\s*)', line)
        indent = len(indent_match.group(1).replace('\t','    '))
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        # Remove stack entries with greater indent
        while stack and stack[-1][0] >= indent:
            stack.pop()
        # class
        m = re.match(r'^\s*class\s+([A-Za-z_]\w*)\s*[:\(]', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            t=Tag(name, file_path, pat, 'c', 'class', idx)
            t.language='Python'
            if stack:
                # scope
                parent = stack[-1]
                t.scope = parent[1]
                t.scopeKind = parent[2]
            tags.append(t)
            stack.append((indent, name, 'class'))
            continue
        # def
        m = re.match(r'^\s*def\s+([A-Za-z_]\w*)\s*\(', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, 96)
            # Determine if inside class => member, else function
            kind = 'm' if stack and stack[-1][2]=='class' else 'f'
            kind_long = 'member' if kind=='m' else 'function'
            t=Tag(name, file_path, pat, kind, kind_long, idx)
            t.language='Python'
            if stack:
                # build scope chain
                # For nesting like Bar.method2.inner, scope should be Bar.method2
                # Our stack contains class and maybe function
                # Build dotted scope
                scope_parts = [s[1] for s in stack]
                t.scope = ".".join(scope_parts) if scope_parts else None
                if scope_parts:
                    # scopeKind is kind of immediate parent
                    t.scopeKind = stack[-1][2]
            # Check if nested inside function, then file scope?
            if len(stack)>=1 and stack[-1][2] in ('function','member'):
                # inner function inside method
                t.file=True
            tags.append(t)
            stack.append((indent, name, kind_long))
            continue
        # variable assignment at module or class level: NAME = ...
        # Only if at indent 0 or inside class
        vm = re.match(r'^\s*([A-Za-z_]\w*)\s*=', line)
        if vm:
            name=vm.group(1)
            # Skip if name is keyword or in function scope? Only allow if inside class or at top level (stack empty or class)
            if stack:
                if stack[-1][2] not in ('class','module'):
                    # if inside function, check if it's at method level but assignment inside class?
                    # For Python, x=1 inside class is variable with class scope
                    if stack[-1][2]=='class':
                        pat=make_pattern(line, 96)
                        t=Tag(name, file_path, pat, 'v', 'variable', idx)
                        t.language='Python'
                        t.scope = stack[-1][1]
                        t.scopeKind = 'class'
                        tags.append(t)
                    continue
                # if inside class, variable
                if stack[-1][2]=='class':
                    pat=make_pattern(line, 96)
                    t=Tag(name, file_path, pat, 'v', 'variable', idx)
                    t.language='Python'
                    t.scope = stack[-1][1]
                    t.scopeKind = 'class'
                    tags.append(t)
                    continue
            else:
                # top level variable: check if upper case maybe? Original includes all caps? Actually FOO = 123 is variable
                pat=make_pattern(line, 96)
                t=Tag(name, file_path, pat, 'v', 'variable', idx)
                t.language='Python'
                tags.append(t)
                continue

