            name=m.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 't', 'type', idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*var\s+([A-Za-z_]\w*)', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 'v', 'var', idx)
            t.language='Go'
            if package:
