def parse_markdown(file_path, content, tags, pattern_limit=96):
    lines=content.splitlines()
    headings=[]
    for idx, line in enumerate(lines, start=1):
        m=re.match(r'^(#{1,5})\s+(.*\S)\s*$', line)
        if m:
            level=len(m.group(1))
            name=m.group(2).strip()
            if level==1:
                kind='c'; kind_long='chapter'
            elif level==2:
                kind='s'; kind_long='section'
            elif level==3:
                kind='S'; kind_long='subsection'
                # Actually S is level2? Let's use mapping from earlier: S=level2, t=level3, T=level4 etc. We'll adjust to original mapping
                # Original mapping: c=chapter (#), s=section (##?), S=level2, t=level3, T=level4, u=level5
                # For simplicity use earlier: level1=c, level2=s, level3=S, level4=t, level5=u? Need to match original.
                # Let's define: level1=c, level2=s, level3=S, level4=t, level5=T? Hmm.
                # Our earlier dump: c=chapter, s=section, S=level2 sections, t=level3, T=level4, u=level5
                # So for ## (level2) should be s or S? In test file, ## Section was s, not S. So level2->s, level3->t? But earlier we saw S is level2 also? This is confusing.
                # We'll define: level2->s, level3->S? No.
                # Actually from dump: S=level2 sections, s=sections, t=level3, etc. So there are two kinds for level2? Maybe '#' vs '##'?
                # For our test, # Title was c, ## Section was s, ### Subsection was S. So level3 was S. That matches: S=level2 sections? Wait level3 is ### should be t per earlier? But our test showed ### Subsection was S? Let's recall: In earlier /tmp/md.md test, we had # Title=c, ## Section=s, ### Subsection=S, ## Another=s. So ### was S.
                # So mapping: level1=c, level2=s, level3=S, level4=t, level5=T, level6=u? Let's use that.
                kind='S'; kind_long='subsection'
            elif level==4:
                kind='t'; kind_long='subsubsection'
            elif level==5:
                kind='T'; kind_long='l4subsection'
            else:
                kind='s'; kind_long='section'
            # Adjust to match earlier mapping more precisely
            if level==1:
                kind='c'; kind_long='chapter'
            elif level==2:
                kind='s'; kind_long='section'
            elif level==3:
                kind='S'; kind_long='subsection'
            elif level==4:
                kind='t'; kind_long='subsubsection'
            elif level==5:
                kind='T'; kind_long='l4subsection'
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, kind, kind_long, idx)
            t.language='Markdown'
            parent_names = [h[1] for h in headings if h[0] < level]
            if parent_names:
                if len(parent_names)==1:
                    t.scope = parent_names[0]
                    parent_level = [h[0] for h in headings if h[0] < level][-1]
                    if parent_level==1:
                        t.scopeKind='chapter'
                    elif parent_level==2:
                        t.scopeKind='section'
                    else:
                        t.scopeKind='section'
                else:
                    t.scope = "\"\"".join(parent_names)
                    parent_level = [h[0] for h in headings if h[0] < level][-1]
                    if parent_level==1:
                        t.scopeKind='chapter'
                    elif parent_level==2:
                        t.scopeKind='section'
                    else:
                        t.scopeKind='section'
            headings = [h for h in headings if h[0] < level]
            headings.append((level, name))
            tags.append(t)

def parse_sh(file_path, content, tags, pattern_limit=96):
    lines=content.splitlines()
    for idx, line in enumerate(lines, start=1):
        m=re.match(r'^\s*([A-Za-z_]\w*)\s*\(\)\s*\{', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 'f', 'function', idx)
            t.language='Sh'
            tags.append(t)

