def parse_file(file_path, language_force=None, guess_eagerly=False, pattern_limit=96):
    try:
        with open(file_path, 'r', errors='ignore') as f:
            content=f.read()
    except Exception as e:
        sys.stderr.write('executable: Warning: cannot open input file "%s" : No such file or directory\n' % file_path)
        return []
    lang = detect_language(file_path, language_force, guess_eagerly)
    if not lang:
        return []
    tags=[]
    if lang == "C":
        parse_c(file_path, content, tags, pattern_limit)
    elif lang == "Python":
        parse_python(file_path, content, tags, pattern_limit)
    elif lang == "Go":
        parse_go(file_path, content, tags, pattern_limit)
    elif lang == "Markdown":
        parse_markdown(file_path, content, tags, pattern_limit)
    elif lang == "Sh":
        parse_sh(file_path, content, tags, pattern_limit)
    elif lang == "JavaScript":
        parse_js(file_path, content, tags, pattern_limit)
    elif lang == "C++":
        # fallback to C for now plus simple class
        parse_c(file_path, content, tags, pattern_limit)
    elif lang == "Java":
        # simple java
        lines=content.splitlines()
        for idx, line in enumerate(lines, start=1):
            m=re.match(r'^\s*(?:public|private|protected)?\s*(?:static)?\s*class\s+([A-Za-z_]\w*)', line)
            if m:
                name=m.group(1)
                pat=make_pattern(line, pattern_limit)
                t=Tag(name, file_path, pat, 'c', 'class', idx)
                t.language='Java'
                tags.append(t)
                continue
            m=re.match(r'^\s*(?:public|private|protected)?\s*(?:static)?\s*(?:[A-Za-z_]\w+\s+)+([A-Za-z_]\w*)\s*\([^)]*\)\s*\{', line)
            if m:
                name=m.group(1)
                if name in ("if","for","while","switch"):
                    continue
                pat=make_pattern(line, pattern_limit)
                t=Tag(name, file_path, pat, 'm', 'method', idx)
                t.language='Java'
                tags.append(t)
    return tags

