def detect_language(file_path, force=None, guess_eagerly=False):
    if force and force != "auto":
        return force
    ext = os.path.splitext(file_path)[1].lower()
    lang = EXT_MAP.get(ext)
    if lang:
        return lang
    base = os.path.basename(file_path)
    if base in ("Makefile", "GNUmakefile", "makefile"):
        return "Make"
    if base == "CMakeLists.txt":
        return "CMake"
    if base == "Cargo.toml":
        return "Cargo"
    try:
        with open(file_path, 'r', errors='ignore') as f:
            first = f.readline()
            if first.startswith("#!"):
                if "python" in first:
                    return "Python"
                if "bash" in first or "sh" in first:
                    return "Sh"
                if "node" in first:
                    return "JavaScript"
    except:
        pass
    return None

def parse_c(file_path, content, tags, pattern_limit=96):
    lines = content.splitlines()
    for idx, line in enumerate(lines, start=1):
        m = re.match(r'^\s*#\s*define\s+([A-Za-z_]\w*)', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 'd', 'macro', idx, file=True)
            t.language='C'
            tags.append(t)
            continue
        if re.match(r'^\s*(if|for|while|switch|return)\b', line.strip()):
            continue
        fm = re.match(r'^\s*(?:[a-zA-Z_][\w\s\*]*?)?\b([A-Za-z_]\w*)\s*\([^)]*\)\s*\{', line)
        if fm:
            name=fm.group(1)
            if name in ("if","for","while","switch","return"):
                continue
            pat=make_pattern(line, pattern_limit)
            m2 = re.match(r'^\s*([A-Za-z_]\w*(?:\s*\*)*)\s+[A-Za-z_]\w*\s*\(', line)
            typ = m2.group(1).strip() if m2 else "int"
            typ = typ.replace(" ","")
            t=Tag(name, file_path, pat, 'f', 'function', idx, typeref=f"typename:{typ}")
            t.language='C'
            tags.append(t)
            continue
        vm = re.match(r'^\s*(?:static\s+|extern\s+|const\s+)*(?:[A-Za-z_]\w*\s+)+([A-Za-z_]\w*)\s*(?:=|;|\[)', line)
        if vm:
            name=vm.group(1)
            if name in ("return","struct","enum","union","typedef","int","char","void","long","short","float","double"):
                continue
            pat=make_pattern(line, pattern_limit)
            m2 = re.match(r'^\s*(?:static\s+|extern\s+|const\s+)*([A-Za-z_]\w*(?:\s*\*)*)', line)
            typ = m2.group(1).strip() if m2 else "int"
            typ = typ.split()[0]
            t=Tag(name, file_path, pat, 'v', 'variable', idx, typeref=f"typename:{typ}")
            t.language='C'
            if 'static' in line:
                t.file=True
            tags.append(t)
            continue
        sm = re.match(r'^\s*struct\s+([A-Za-z_]\w*)\s*\{', line)
        if sm:
            name=sm.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 's', 'struct', idx, file=True)
            t.language='C'
            tags.append(t)
            continue
        em = re.match(r'^\s*enum\s+([A-Za-z_]\w*)\s*\{', line)
        if em:
            name=em.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 'g', 'enum', idx, file=True)
            t.language='C'
            tags.append(t)
            continue

def parse_python(file_path, content, tags, pattern_limit=96):
    lines = content.splitlines()
    stack = []
    for idx, line in enumerate(lines, start=1):
        indent_match = re.match(r'^(\s*)', line)
        indent = len(indent_match.group(1).replace('\t','    '))
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        while stack and stack[-1][0] >= indent:
            stack.pop()
        m = re.match(r'^\s*class\s+([A-Za-z_]\w*)\s*[:\(]', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, pattern_limit)
            t=Tag(name, file_path, pat, 'c', 'class', idx)
            t.language='Python'
            if stack:
                parent = stack[-1]
                t.scope = parent[1]
                t.scopeKind = parent[2]
            tags.append(t)
            stack.append((indent, name, 'class'))
            continue
        m = re.match(r'^\s*def\s+([A-Za-z_]\w*)\s*\(', line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, pattern_limit)
            kind = 'm' if stack and stack[-1][2]=='class' else 'f'
            kind_long = 'member' if kind=='m' else 'function'
            t=Tag(name, file_path, pat, kind, kind_long, idx)
            t.language='Python'
            if stack:
                scope_parts = [s[1] for s in stack]
                t.scope = ".".join(scope_parts) if scope_parts else None
                if scope_parts:
                    t.scopeKind = stack[-1][2]
            if len(stack)>=1 and stack[-1][2] in ('function','member'):
                t.file=True
            tags.append(t)
            stack.append((indent, name, kind_long))
            continue
        vm = re.match(r'^\s*([A-Za-z_]\w*)\s*=', line)
        if vm:
            name=vm.group(1)
            if stack:
                if stack[-1][2]=='class':
                    pat=make_pattern(line, pattern_limit)
                    t=Tag(name, file_path, pat, 'v', 'variable', idx)
                    t.language='Python'
                    t.scope = stack[-1][1]
                    t.scopeKind = 'class'
                    tags.append(t)
                    continue
            else:
                pat=make_pattern(line, pattern_limit)
                t=Tag(name, file_path, pat, 'v', 'variable', idx)
                t.language='Python'
                tags.append(t)
                continue

