        lang_tokens = opts["languages"].split(",")
        include_set=set()
        exclude_set=set()
        has_plus_minus=False
        for tok in lang_tokens:
            tok=tok.strip()
            if not tok:
                continue
            if tok[0]=="+":
                has_plus_minus=True
                include_set.add(tok[1:])
            elif tok[0]=="-":
                has_plus_minus=True
                exclude_set.add(tok[1:])
            else:
                include_set.add(tok)
        if not has_plus_minus:
            allowed=include_set
        else:
            if include_set:
                allowed=include_set
            else:
                allowed=None
        for fp in expanded_files:
