                    line_content = lines[t.line-1].strip() if 1<=t.line<=len(lines) else ""
            except:
                line_content=""
            if opts["xformat"]:
                fmt = opts["xformat"]
                def repl_x(m):
                    spec = m.group(0)
                    letter = spec[-1]
                    if letter == 'N':
