def parse_file(file_path, language_force=None, guess_eagerly=False, pattern_limit=96):
    try:
        with open(file_path,'r',errors='ignore') as f:
            content=f.read()
    except Exception:
        sys.stderr.write('executable: Warning: cannot open input file "%s" : No such file or directory\n' % file_path)
        return []
    lang=detect_language(file_path, language_force, guess_eagerly)
    if not lang:
        return []
    tags=[]
    if lang=="C":
        parse_c(file_path,content,tags,pattern_limit)
    elif lang=="Python":
        parse_python(file_path,content,tags,pattern_limit)
    elif lang=="Go":
        parse_go(file_path,content,tags,pattern_limit)
    elif lang=="Markdown":
        parse_markdown(file_path,content,tags,pattern_limit)
    elif lang=="Sh":
        parse_sh(file_path,content,tags,pattern_limit)
    elif lang=="JavaScript":
        parse_js(file_path,content,tags,pattern_limit)
    elif lang=="C++":
        parse_c(file_path,content,tags,pattern_limit)
    elif lang=="Java":
        lines=content.splitlines()
        for idx,line in enumerate(lines, start=1):
            m=re.match(r'^\s*(?:public|private|protected)?\s*(?:static)?\s*class\s+([A-Za-z_]\w*)',line)
            if m:
                name=m.group(1)
                pat=make_pattern(line, pattern_limit)
                t=Tag(name,file_path,pat,'c','class',idx)
                t.language='Java'
                tags.append(t)
                continue
            m=re.match(r'^\s*(?:public|private|protected)?\s*(?:static)?\s*(?:[A-Za-z_]\w+\s+)+([A-Za-z_]\w*)\s*\([^)]*\)\s*\{',line)
            if m:
                name=m.group(1)
                if name in ("if","for","while","switch"):
                    continue
                pat=make_pattern(line, pattern_limit)
                t=Tag(name,file_path,pat,'m','method',idx)
                t.language='Java'
                tags.append(t)
    return tags

def main():
    argv=sys.argv[1:]
    expanded=[]
    i=0
    while i < len(argv):
        a=argv[i]
        if a.startswith("--options="):
            path=a.split("=",1)[1]
            if path!="NONE":
                try:
                    with open(path) as ff:
                        for line in ff:
                            line=line.strip()
                            if not line or line.startswith("#"):
                                continue
                            expanded.extend(shlex.split(line))
                except FileNotFoundError:
                    sys.stderr.write('executable: cannot stat "%s" : No such file or directory\n' % path)
                    sys.exit(1)
            i+=1
            continue
        elif a=="--options" or a=="--options-maybe":
            if i+1 < len(argv):
                path=argv[i+1]
                if path!="NONE":
                    try:
                        with open(path) as ff:
                            for line in ff:
                                line=line.strip()
                                if not line or line.startswith("#"):
                                    continue
                                expanded.extend(shlex.split(line))
                    except FileNotFoundError:
                        if a=="--options":
                            sys.stderr.write('executable: cannot stat "%s" : No such file or directory\n' % path)
                            sys.exit(1)
                i+=2
                continue
            else:
                i+=1
                continue
        else:
            expanded.append(a)
            i+=1
    argv=expanded

    handle_early_lists(argv)
    handle_version_help(argv)

    opts={
        "recurse": False,
        "exclude": [],
        "exclude_exception": [],
        "filter": False,
        "filter_terminator": None,
        "links": True,
        "maxdepth": None,
        "append": False,
        "tagfile": "tags",
        "output_format": "u-ctags",
        "sort": "yes",
        "language_force": None,
        "languages": None,
        "guess_eagerly": False,
        "excmd": "mix",
        "pattern_length_limit": 96,
        "tag_relative": "no",
        "totals": None,
        "quiet": False,
        "verbose": False,
        "format": 2,
        "xformat": None,
        "files": [],
        "list_file": None,
        "fields_enabled": set(['f','k','s','t','N','F','P']),
        "fields_extra": {},
    }

    i=0
    while i < len(argv):
        a=argv[i]
        if a=="-R" or a=="--recurse" or a.startswith("--recurse="):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["recurse"]= v.lower() not in ("no","false","0")
            else:
                opts["recurse"]=True
            i+=1
            continue
        if a.startswith("--exclude="):
            opts["exclude"].append(a.split("=",1)[1])
            i+=1
            continue
        if a.startswith("--exclude-exception="):
            opts["exclude_exception"].append(a.split("=",1)[1])
            i+=1
            continue
        if a.startswith("--filter"):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["filter"]= v.lower() not in ("no","false","0")
            else:
                opts["filter"]=True
            i+=1
            continue
        if a.startswith("--filter-terminator="):
            opts["filter_terminator"]=a.split("=",1)[1]
            i+=1
            continue
        if a.startswith("--links"):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["links"]= v.lower() not in ("no","false","0")
            else:
                opts["links"]=True
            i+=1
            continue
        if a.startswith("--maxdepth="):
            try:
                opts["maxdepth"]=int(a.split("=",1)[1])
            except:
                sys.stderr.write('executable: -maxdepth: Invalid maximum recursion depth\n')
                sys.exit(1)
            i+=1
            continue
        if a=="-L":
            if i+1 < len(argv):
                opts["list_file"]=argv[i+1]
                i+=2
            else:
                i+=1
            continue
        if a.startswith("-L"):
            val=a[2:]
            if val:
                opts["list_file"]=val
            i+=1
            continue
        if a.startswith("--append") or a=="-a":
            if "=" in a:
                v=a.split("=",1)[1]
                opts["append"]= v.lower() not in ("no","false","0")
            else:
                opts["append"]=True
            i+=1
            continue
        if a=="-f" or a=="-o":
            if i+1 < len(argv):
                opts["tagfile"]=argv[i+1]
                i+=2
            else:
                i+=1
            continue
        if a.startswith("-f"):
            val=a[2:]
            if val:
                opts["tagfile"]=val
            i+=1
            continue
        if a.startswith("-o"):
            val=a[2:]
            if val:
                opts["tagfile"]=val
            i+=1
            continue
        if a.startswith("--output=") or a.startswith("--tagfile="):
            opts["tagfile"]=a.split("=",1)[1]
            i+=1
            continue
        if a=="--format" or a.startswith("--format="):
            if "=" in a:
                try:
                    v=int(a.split("=",1)[1])
                    if v not in (1,2):
                        raise ValueError
                    opts["format"]=v
                except:
                    sys.stderr.write('executable: Unsupported value for "format" option\n')
                    sys.exit(1)
            else:
                if i+1 < len(argv):
                    try:
                        v=int(argv[i+1])
                        if v not in (1,2):
                            raise ValueError
                        opts["format"]=v
                        i+=1
                    except:
                        sys.stderr.write('executable: Unsupported value for "format" option\n')
                        sys.exit(1)
            i+=1
            continue
        if a.startswith("--output-format="):
            fmt=a.split("=",1)[1]
            if fmt not in ("u-ctags","e-ctags","etags","xref","json"):
                sys.stderr.write('executable: unknown output format name supplied for "output-format=%s"\n' % fmt)
                sys.exit(1)
            opts["output_format"]=fmt
            i+=1
            continue
        if a=="-e":
            opts["output_format"]="etags"
            i+=1
            continue
        if a=="-x":
            opts["output_format"]="xref"
            i+=1
            continue
        if a.startswith("--sort"):
            if "=" in a:
                v=a.split("=",1)[1]
                if v not in ("yes","no","foldcase"):
                    sys.stderr.write('executable: Invalid value for "sort" option\n')
                    sys.exit(1)
                opts["sort"]=v
            else:
                opts["sort"]="yes"
            i+=1
            continue
        if a=="-u":
            opts["sort"]="no"
            i+=1
            continue
        if a.startswith("--etags-include="):
            i+=1
            continue
        if a.startswith("--input-encoding=") or a.startswith("--output-encoding=") or a.startswith("--input-encoding-"):
            i+=1
            continue
        if a.startswith("--language-force="):
            opts["language_force"]=a.split("=",1)[1]
            ld=get_list_content("list-languages")
            clean=[]
            if ld:
                for l in ld.splitlines():
                    clean.append(l.split()[0])
            lang_force=opts["language_force"]
            if lang_force!="auto" and lang_force not in clean:
                sys.stderr.write('executable: Unknown language "%s" in "language-force" option\n' % lang_force)
                sys.exit(1)
            i+=1
            continue
        if a.startswith("--languages="):
            opts["languages"]=a.split("=",1)[1]
            ld=get_list_content("list-languages")
            clean=[]
            if ld:
                for l in ld.splitlines():
                    clean.append(l.split()[0])
            for token in opts["languages"].split(","):
                t=token.strip()
                if not t:
                    continue
                if t[0] in "+-":
                    t=t[1:]
                if t=="all":
                    continue
                if t not in clean:
                    sys.stderr.write('executable: Warning: Unknown language "%s" in "languages" option\n' % t)
            i+=1
            continue
        if a.startswith("--alias-"):
            i+=1
            continue
        if a=="-G" or a=="--guess-language-eagerly":
            opts["guess_eagerly"]=True
            i+=1
            continue
        if a.startswith("--guess-language-eagerly"):
            if "=" in a:
                v=a.split("=",1)[1]
                opts["guess_eagerly"]= v.lower() not in ("no","false","0")
            else:
                opts["guess_eagerly"]=True
            i+=1
            continue
        if a.startswith("--langmap="):
            i+=1
            continue
        if a.startswith("--map-"):
            i+=1
            continue
        if a.startswith("--excmd="):
            v=a.split("=",1)[1]
            if v not in ("number","pattern","mix","combine"):
                sys.stderr.write('executable: Invalid value for "excmd" option\n')
                sys.exit(1)
            opts["excmd"]=v
            i+=1
            continue
        if a=="-n":
            opts["excmd"]="number"
            i+=1
            continue
        if a=="-N":
            opts["excmd"]="pattern"
            i+=1
            continue
        if a.startswith("--extras=") or a.startswith("--extras-"):
            # Handle extras like +f etc
            if "=" in a:
                val=a.split("=",1)[1]
