            tags.append(t)
            continue
        m=re.match(r'^\s*type\s+([A-Za-z_]\w*)\s+interface',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'i','interface',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*type\s+([A-Za-z_]\w*)\s+',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'t','type',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
