def handle_version_help(argv):
    for arg in argv:
        if arg == "--version":
            sys.stdout.write(VERSION+"\n")
            sys.exit(0)
        if arg.startswith("--version="):
            lang = arg.split("=",1)[1]
            data = load_data_file(f"describe-{lang}.txt")
            ver="1.1"
            if data:
                m=re.search(r"version:\s*([0-9\.]+)", data)
                if m:
                    ver=m.group(1)
            sys.stdout.write("%s %s\n" % (lang, ver))
            sys.exit(0)
        if arg in ("--help","-?"):
            if HELP_TEXT:
                sys.stdout.write(HELP_TEXT)
                if not HELP_TEXT.endswith("\n"):
                    sys.stdout.write("\n")
            else:
                sys.stdout.write(VERSION+"\nUsage: executable [options] [file(s)]\n")
            sys.exit(0)
        if arg == "--help-full":
            if HELP_FULL_TEXT:
                sys.stdout.write(HELP_FULL_TEXT)
                if not HELP_FULL_TEXT.endswith("\n"):
                    sys.stdout.write("\n")
            else:
                sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        if arg == "--license":
            try:
                with open("COPYING") as f:
                    sys.stdout.write(f.read())
            except:
                txt=load_data_file("license.txt")
                if txt:
                    sys.stdout.write(txt+"\n")
            sys.exit(0)

class Tag:
    def __init__(self, name, path, pattern, kind, kind_long, line, typeref=None, scope=None, scopeKind=None, file=False):
        self.name=name
        self.path=path
        self.pattern=pattern
        self.kind=kind
        self.kind_long=kind_long
        self.line=line
        self.typeref=typeref
        self.scope=scope
        self.scopeKind=scopeKind
        self.file=file
        self.language=None

def escape_pattern(line, limit=96):
    escaped=""
    orig_len=0
    for idx, ch in enumerate(line):
        if ch == "/":
            esc = "\\/"
        elif ch == "\\":
            esc = "\\\\"
        elif ch == "$" and idx == len(line)-1:
            esc = "\\$"
        else:
            esc = ch
        if limit>0 and len(escaped)+len(esc) > limit:
            break
        escaped+=esc
        orig_len=idx+1
    truncated = (orig_len < len(line)) if limit>0 else False
    if truncated:
        return f"/^{escaped}/"
    else:
        return f"/^{escaped}$/"

def make_pattern(line, limit=96):
    return escape_pattern(line.rstrip("\n"), limit)

REGEX_DEFS = {}
MLINE_REGEX_DEFS = {}
LANG_DEFS = set()

EXT_MAP = {
    ".c": "C", ".h": "C", ".cpp": "C++", ".cc": "C++", ".hpp": "C++",
    ".py": "Python", ".pyw": "Python", ".pyx": "Python", ".pxd": "Python", ".pxi": "Python",
    ".go": "Go", ".js": "JavaScript", ".jsx": "JavaScript", ".mjs": "JavaScript",
    ".java": "Java", ".sh": "Sh", ".bash": "Sh",
    ".md": "Markdown", ".markdown": "Markdown",
    ".rs": "Rust", ".rb": "Ruby", ".php": "PHP", ".pl": "Perl", ".pm": "Perl",
    ".ts": "TypeScript", ".lua": "Lua", ".html": "HTML", ".htm": "HTML",
    ".css": "CSS", ".json": "JSON", ".xml": "XML", ".yaml": "Yaml", ".yml": "Yaml",
}

def detect_language(file_path, force=None, guess_eagerly=False):
    if force and force != "auto":
        return force
    ext = os.path.splitext(file_path)[1].lower()
    lang = EXT_MAP.get(ext)
    if lang:
        return lang
    base = os.path.basename(file_path)
    if base in ("Makefile","GNUmakefile","makefile"):
        return "Make"
    if base == "CMakeLists.txt":
        return "CMake"
    if base == "Cargo.toml":
        return "Cargo"
    try:
        with open(file_path,'r',errors='ignore') as f:
            first=f.readline()
            if first.startswith("#!"):
                if "python" in first:
                    return "Python"
                if "bash" in first or "sh" in first:
                    return "Sh"
                if "node" in first:
                    return "JavaScript"
    except:
        pass
    return None

def parse_c(file_path, content, tags, limit=96, if0=False):
    lines=content.splitlines()
    filtered=[]
    skip_depth=0
    for l in lines:
        stripped=l.strip()
        if stripped.startswith("#if 0"):
            if not if0:
                skip_depth+=1
            filtered.append((l, True))
            continue
        if stripped.startswith("#endif"):
            if skip_depth>0:
                skip_depth-=1
                filtered.append((l, True))
                continue
            filtered.append((l, False))
            continue
        if skip_depth>0:
            filtered.append((l, True))
        else:
            filtered.append((l, False))
    for idx, (line, is_skipped) in enumerate(filtered, start=1):
        if is_skipped and not if0:
            continue
        m=re.match(r'^\s*#\s*define\s+([A-Za-z_]\w*)',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'d','macro',idx,file=True)
            t.language='C'
            tags.append(t)
            continue
        if re.match(r'^\s*(if|for|while|switch|return)\b', line.strip()):
            continue
        fm=re.match(r'^\s*(?:[a-zA-Z_][\w\s\*]*?)?\b([A-Za-z_]\w*)\s*\([^)]*\)\s*\{',line)
        if fm:
            name=fm.group(1)
            if name in ("if","for","while","switch","return"):
                continue
            pat=make_pattern(line, limit)
            m2=re.match(r'^\s*([A-Za-z_]\w*(?:\s*\*)*)\s+[A-Za-z_]\w*\s*\(',line)
            typ=m2.group(1).strip() if m2 else "int"
            typ=typ.replace(" ","")
            t=Tag(name,file_path,pat,'f','function',idx,typeref=f"typename:{typ}")
            t.language='C'
            tags.append(t)
            continue
        vm=re.match(r'^\s*(?:static\s+|extern\s+|const\s+)*(?:[A-Za-z_]\w*\s+)+([A-Za-z_]\w*)\s*(?:=|;|\[)',line)
        if vm:
            name=vm.group(1)
            if name in ("return","struct","enum","union","typedef","int","char","void","long","short","float","double"):
                continue
            pat=make_pattern(line, limit)
            m2=re.match(r'^\s*(?:static\s+|extern\s+|const\s+)*([A-Za-z_]\w*(?:\s*\*)*)',line)
            typ=m2.group(1).strip() if m2 else "int"
            typ=typ.split()[0]
            t=Tag(name,file_path,pat,'v','variable',idx,typeref=f"typename:{typ}")
            t.language='C'
            if 'static' in line:
                t.file=True
            tags.append(t)
            continue
        sm=re.match(r'^\s*struct\s+([A-Za-z_]\w*)\s*\{',line)
        if sm:
            name=sm.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'s','struct',idx,file=True)
            t.language='C'
            tags.append(t)
            continue
        em=re.match(r'^\s*enum\s+([A-Za-z_]\w*)\s*\{',line)
        if em:
            name=em.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'g','enum',idx,file=True)
            t.language='C'
            tags.append(t)
            continue

def parse_python(file_path, content, tags, limit=96):
    lines=content.splitlines()
    stack=[]
    for idx,line in enumerate(lines, start=1):
        indent_match=re.match(r'^(\s*)',line)
        indent=len(indent_match.group(1).replace('\t','    '))
        stripped=line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        while stack and stack[-1][0]>=indent:
            stack.pop()
        m=re.match(r'^\s*class\s+([A-Za-z_]\w*)\s*[:\(]',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'c','class',idx)
            t.language='Python'
            if stack:
                parent=stack[-1]
                t.scope=parent[1]
                t.scopeKind=parent[2]
            tags.append(t)
            stack.append((indent,name,'class'))
            continue
        m=re.match(r'^\s*def\s+([A-Za-z_]\w*)\s*\(',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            kind='m' if stack and stack[-1][2]=='class' else 'f'
            kind_long='member' if kind=='m' else 'function'
            t=Tag(name,file_path,pat,kind,kind_long,idx)
            t.language='Python'
            if stack:
                scope_parts=[s[1] for s in stack]
                t.scope=".".join(scope_parts) if scope_parts else None
                if scope_parts:
                    t.scopeKind=stack[-1][2]
            if len(stack)>=1 and stack[-1][2] in ('function','member'):
                t.file=True
            tags.append(t)
            stack.append((indent,name,kind_long))
            continue
        vm=re.match(r'^\s*([A-Za-z_]\w*)\s*=',line)
        if vm:
            name=vm.group(1)
            if stack:
                if stack[-1][2]=='class':
                    pat=make_pattern(line, limit)
                    t=Tag(name,file_path,pat,'v','variable',idx)
                    t.language='Python'
                    t.scope=stack[-1][1]
                    t.scopeKind='class'
                    tags.append(t)
                    continue
            else:
                pat=make_pattern(line, limit)
                t=Tag(name,file_path,pat,'v','variable',idx)
                t.language='Python'
                tags.append(t)
                continue

def parse_go(file_path, content, tags, limit=96):
    lines=content.splitlines()
    package=None
    for idx,line in enumerate(lines, start=1):
        m=re.match(r'^\s*package\s+([A-Za-z_]\w*)',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'p','package',idx)
            t.language='Go'
            tags.append(t)
            package=name
            continue
        m=re.match(r'^\s*func\s+(?:\([^\)]+\))?\s*([A-Za-z_]\w*)\s*\(',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'f','func',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*type\s+([A-Za-z_]\w*)\s+struct',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'s','struct',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*type\s+([A-Za-z_]\w*)\s+interface',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'i','interface',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*type\s+([A-Za-z_]\w*)\s+',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'t','type',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*var\s+([A-Za-z_]\w*)',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'v','var',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue
        m=re.match(r'^\s*const\s+([A-Za-z_]\w*)',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'c','const',idx)
            t.language='Go'
            if package:
                t.scope=package
                t.scopeKind='package'
            tags.append(t)
            continue

def parse_markdown(file_path, content, tags, limit=96):
    lines=content.splitlines()
    headings=[]
    for idx,line in enumerate(lines, start=1):
        m=re.match(r'^(#{1,5})\s+(.*\S)\s*$',line)
        if m:
            level=len(m.group(1))
            name=m.group(2).strip()
            if level==1:
                kind='c'; kind_long='chapter'
            elif level==2:
                kind='s'; kind_long='section'
            elif level==3:
                kind='S'; kind_long='subsection'
            elif level==4:
                kind='t'; kind_long='subsubsection'
            elif level==5:
                kind='T'; kind_long='l4subsection'
            else:
                kind='s'; kind_long='section'
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,kind,kind_long,idx)
            t.language='Markdown'
            parent_names=[h[1] for h in headings if h[0]<level]
            if parent_names:
                if len(parent_names)==1:
                    t.scope=parent_names[0]
                    parent_level=[h[0] for h in headings if h[0]<level][-1]
                    if parent_level==1:
                        t.scopeKind='chapter'
                    elif parent_level==2:
                        t.scopeKind='section'
                    else:
                        t.scopeKind='section'
                else:
                    t.scope="\"\"".join(parent_names)
                    parent_level=[h[0] for h in headings if h[0]<level][-1]
                    if parent_level==1:
                        t.scopeKind='chapter'
                    elif parent_level==2:
                        t.scopeKind='section'
                    else:
                        t.scopeKind='section'
            headings=[h for h in headings if h[0]<level]
            headings.append((level,name))
            tags.append(t)

def parse_sh(file_path, content, tags, limit=96):
    lines=content.splitlines()
    for idx,line in enumerate(lines, start=1):
        m=re.match(r'^\s*([A-Za-z_]\w*)\s*\(\)\s*\{',line)
        if m:
            name=m.group(1)
            pat=make_pattern(line, limit)
            t=Tag(name,file_path,pat,'f','function',idx)
            t.language='Sh'
            tags.append(t)

